fn shown(s:&str)->String{s.chars().flat_map(|c|{let v=match c{'\n'=>"↵".into(),'\t'=>"    ".into(),'\x7f'=>"^?".into(),c if (c as u32)<32=>format!("^{}",char::from_u32(c as u32+64).unwrap_or('?')),c if c.is_control()||matches!(c,'\u{202a}'..='\u{202e}'|'\u{2066}'..='\u{2069}')=>format!("\\u{{{:x}}}",c as u32),_=>c.to_string()};v.chars().collect::<Vec<_>>()}).collect()}
fn projected(e:&Editor)->Result<(String,usize)>{e.valid()?;let mut out=String::new();let mut caret=0;let mut at=0;let push=|a:usize,b:usize,out:&mut String,caret:&mut usize|{for(x,y,_)in clusters(&e.text[a..b]){out.push_str(&shown(&e.text[a+x..a+y]));if a+y<=e.at{*caret=out.len();}}};if !e.unfolded{for f in &e.f{push(at,f.a,&mut out,&mut caret);out.push_str(&format!("[粘贴 {} 行 · {} 字]",f.lines,f.chars));if f.b<=e.at{caret=out.len()}at=f.b;}}push(at,e.text.len(),&mut out,&mut caret);Ok((out,caret))}
/// Pure input projection. Control bytes are displayed; original text is unchanged.
/// The upstream width approximation keeps an overwide cluster whole at width 1.
/// Actual terminal frames reserve at least two input columns.
pub fn input_frame(e:&Editor,prompt:&str,w:usize,max:usize)->Result<InputFrame>{if !(1..=1000).contains(&w)||!(1..=1000).contains(&max)||prompt.len()>128{return Err(Error::usage("input frame dimensions or prompt exceed budget"))}let prompt=sanitize(prompt);let pw=width(&prompt);let prompt=if pw<w{prompt.as_str()}else{""};let lead=if pw<w{pw}else{0};let avail=w-lead;let(display,caret)=projected(e)?;let mut all=Vec::new();let mut start=0;let mut used=0;let mut col=0;for(a,b,c)in clusters(&display){if b<=caret{col+=c}if used+c>avail&&a>start{all.push((display[start..a].to_owned(),used));start=a;used=0}used+=c;if used>avail{all.push((display[start..b].to_owned(),used));start=b;used=0;}}if start<display.len(){all.push((display[start..].into(),used))}if all.is_empty(){all.push((String::new(),0))}let mut row=0;let mut before=0;while row<all.len(){let n=all[row].1;if n==0||col<before+n||row==all.len()-1&&col==before+n&&n<avail{break}before+=n;row+=1;}if row>=all.len(){all.push((String::new(),0))}let top=if row<max{0}else{row-max+1}.min(all.len().saturating_sub(max));let end=(top+max).min(all.len());let head=if top==0{prompt.to_owned()}else{format!("…{}"," ".repeat(lead.saturating_sub(1)))};let rows=all[top..end].iter().enumerate().map(|(i,(s,_))|format!("{}{s}",if i==0{head.clone()}else{" ".repeat(lead)})).collect();Ok(InputFrame{rows,caret:Caret{row:row-top,col:lead+col-before},hidden:Hidden{above:top,below:all.len()-end}})}
fn frame0(v:&Value,o:&Value,e:&Editor)->Result<(Vec<String>,Caret)>{e.valid()?;let w=n(o,"width",80,1,1000)? as usize;let h=n(o,"height",12,1,1000)? as usize;if w.checked_mul(h).is_none_or(|x|x>200000){return Err(Error::usage("terminal frame area exceeds budget"))}if h<5||w<4{return Ok((vec![cell("terminal too small (need width 4 and height 5)",w)],Caret{row:0,col:0}))}let input=input_frame(e,"> ",w,3.min(h-4))?;let mut body=probe::lines(v,o)?;if let Some(x)=o.get("overlay"){let a=x.as_array().filter(|x|x.len()<=util::MAX_EVENTS).ok_or_else(||Error::usage("overlay must be bounded line array"))?;body=a.iter().map(|x|x.as_str().map(str::to_owned).ok_or_else(||Error::usage("overlay line must be string"))).collect::<Result<Vec<_>>>()?;}let top=n(o,"scroll",0,0,util::MAX_EVENTS as u64)? as usize;let b=h-input.rows.len()-3;let count=body.len().saturating_sub(top).min(b);let mut out=vec![cell(&format!("┌ Fugue{}",o.get("focus").and_then(Value::as_str).map(|x|format!(" · {x}")).unwrap_or_default()),w)];for line in body.iter().skip(top).take(count){out.push(format!("│{}│",cell(line,w-2)))}if body.len()>top+count&&count>0{let i=out.len()-1;out[i]=format!("│{}│",cell(&format!("… {} more rows (PgUp/PgDn)",body.len()-top-count),w-2))}while out.len()<h-input.rows.len()-2{out.push(format!("│{}│"," ".repeat(w-2)))}out.push(cell(&format!("└{}","─".repeat(w-1)),w));out.push(cell(o.get("note").and_then(Value::as_str).unwrap_or("g approval · Tab focus · r read · ? help · q quit"),w));let caret=Caret{row:out.len()+input.caret.row,col:input.caret.col};out.extend(input.rows.iter().map(|s|format!("{s}{}"," ".repeat(w.saturating_sub(width(s))))));Ok((out,caret))}
pub fn frame(v:&Value,o:&Value)->Result<Vec<String>>{let mut e=Editor::default();if let Some(x)=o.get("input"){e.text=x.as_str().ok_or_else(||Error::usage("input must be string"))?.into();}e.at=n(o,"caret",e.text.len() as u64,0,B as u64)? as usize;Ok(frame0(v,o,&e)?.0)}
pub fn words(line:&str)->Result<Vec<String>>{if line.len()>B||line.contains('\0'){return Err(Error::usage("command exceeds input budget or contains NUL"))}let t=line.trim();if t.is_empty(){return Err(Error::usage("empty command"))}if t.starts_with('!'){return Err(Error::usage("shell escape is forbidden; use a Fugue command"))}let mut out=vec![];let mut one=String::new();let mut quote=None;let mut have=false;for c in t.chars(){if let Some(q)=quote{if c==q{quote=None}else{one.push(c)}have=true;continue}if c=='\''||c=='"'{quote=Some(c);have=true}else if c.is_whitespace(){if have{out.push(std::mem::take(&mut one));have=false}}else{one.push(c);have=true}if out.len()>256{return Err(Error::usage("too many command arguments"))}}if quote.is_some(){return Err(Error::usage("unclosed command quote"))}if have{out.push(one)}if out.is_empty(){return Err(Error::usage("empty command"))}if out.len()>256{return Err(Error::usage("too many command arguments"))}Ok(out)}
